export type PersonId =
  | "noa" | "finance"
  | "marco" | "aaliyah" | "wei" | "priya" | "dima" | "carmen" | "kwame" | "fatima" | "shiv";

export type Category =
  | "meals" | "travel_air" | "travel_ground" | "lodging" | "conference_training"
  | "entertainment" | "software" | "equipment" | "other";

/** What the agent did with the claim. */
export type AgentOutcome = "auto_approved" | "chasing" | "escalated" | "auto_declined";

/** Where the claim stands right now. Use this for tabs and filters. */
export type Status =
  | "approved_by_agent" | "approved_by_noa"
  | "declined_by_agent" | "declined_by_noa"
  | "waiting_on_employee" | "waiting_on_noa" | "waiting_on_finance";

export type ReasonType =
  | "within_policy" | "over_meal_cap" | "receipt_missing" | "receipt_unreadable"
  | "receipt_missing_unresolved" | "over_finance_threshold" | "no_matching_rule"
  | "currency_mismatch" | "possible_duplicate" | "possible_split" | "unusual_amount" | "unusual_pattern";

export type CheckResult = "pass" | "fail" | "flag" | "unsure" | "skipped";
export type RuleId = "meal_cap" | "receipt_required" | "finance_over_1000";

export interface Person {
  id: PersonId;
  name: string;
  role: "manager" | "finance_approver" | "team_member";
  based_in: "Stockholm" | null;
}

export interface Money { value: number; currency: "USD" | "EUR" | "SEK"; }

export interface FxBlock {
  rate: number;
  rate_date: string;
  rate_source: string;
  usd_computed: number;   // original.value * rate
  gap_usd: number;        // usd_claimed - usd_computed
  gap_pct: number;        // absolute, percent
  tolerance_pct: number;
}

export interface ReceiptLine { label: string; amount: number; }

/** What is printed on the receipt, or what the agent read from it. */
export interface ReceiptRead {
  merchant: string;
  date: string;
  currency: "USD" | "EUR" | "SEK";
  lines: ReceiptLine[];
  subtotal: number | null;
  tax: number | null;
  tip: number | null;
  total: number | null;
  covers: number | null;               // number of diners printed on a restaurant receipt
  details: Record<string, string | number>;  // ride_id, invoice, nights, route, ...
}

export interface Receipt {
  status: "attached" | "missing" | "unreadable";
  /** The truth: what the paper receipt says. Render the receipt view from this. */
  document: ReceiptRead | null;
  /** What the agent extracted. Equals document except where the agent misread. */
  agent_read: ReceiptRead | null;
  attachments: { kind: string; label: string; shows: string }[];
}

export interface Check {
  id: string;
  label: string;
  result: CheckResult;
  detail: string;
  rule_id: RuleId | null;
}

export interface ChaseAttempt {
  sent_at: string;
  message: string;
  reply: { at: string; text: string; attachments: string[] } | null;
}

export interface Agent {
  outcome: AgentOutcome;
  reason_type: ReasonType;
  /** One line, safe to show in a list row. */
  headline: string;
  /** Two or three sentences in plain language. */
  explanation: string;
  cited_rule_ids: RuleId[];
  facts: { label: string; value: string }[];
  checks: Check[];
  /** True when the agent says it could not judge. Ramp's "unsure". */
  unsure: boolean;
  /** The question the agent is asking Noa. Null unless outcome is "escalated". */
  needs_from_noa: string | null;
  policy_version: string;
  decided_at: string;
  chase: null | {
    max_attempts: number;
    status: "waiting" | "unresolved";
    attempts: ChaseAttempt[];
    next_attempt_at: string | null;
    escalates_at: string;
  };
  related_claim_ids: string[];
}

export interface NoaDecision {
  decision: "approved" | "declined";
  decided_at: string;
  note: string;
  approved_amount_usd: number;
  overrode_agent: boolean;
}

export interface ClaimEvent {
  at: string;
  actor: "employee" | "agent" | "noa" | "finance" | "system";
  type: "submitted" | "agent_decision" | "chase_sent" | "employee_replied" | "noa_decision";
  text: string;
}

export interface Claim {
  id: string;                          // "C-1001"
  employee_id: PersonId;
  submitted_at: string;
  expense_date: string;
  category: Category;
  merchant: string;
  description: string;
  employee_note: string | null;
  attendees: { count: number; ids: string[] };   // ids may include "ext_*" guests
  amount: { original: Money; usd_claimed: number; fx: FxBlock | null };
  receipt: Receipt;
  story_moments: number[];             // 1 to 8, see Story.md
  agent: Agent;
  status: Status;
  awaiting: "noa" | "employee" | "finance" | null;
  approval_chain: {
    step: "agent" | "noa" | "finance";
    state: "done" | "waiting" | "skipped" | "not_needed";
  }[];
  noa: NoaDecision | null;
  events: ClaimEvent[];
}

export interface PolicyRule {
  id: RuleId;
  text: string;
  type: string;
  category?: Category;
  limit_usd?: number;
  threshold_usd?: number;
  approver?: string;
  source: "assignment";
}

export interface Dataset {
  meta: {
    dataset: string;
    version: string;
    generated_on: string;
    now: string;                       // treat as the current time in the prototype
    week: { start: string; end: string };
    currency: "USD";
    company: { name: string; note: string };
    manager_id: "noa";
    finance_id: "finance";
    baseline: {
      avg_days_to_approval: number;
      goal_days_to_approval: number;
      weekly_claims_a_year_ago: number;
      weekly_claims_now: number;
      minutes_per_claim_today: [number, number];
      steps_per_claim_today: number;
    };
    counts: Record<string, number>;
  };
  assumptions: string[];
  policy: {
    version: string;
    rules: PolicyRule[];
    agent_settings: Record<string, unknown>;
  };
  people: Person[];
  /** Default UI labels. Change freely. */
  enums: Record<string, Record<string, string>>;
  claims: Claim[];
}
